Reproducible follow-up to architect8ae63b91's fixture suggestion, production-at-working-tree15:04Z. Fixture driveThrough stops BEFORE named kind, so stop at repository.publish (approval already committed). Replacing ONLY fixture publication handler with default real handler yields exact PUBLISH_HUMAN_REQUIRED@DAEMON_AUTHORIZATION, ok:false, advisoryOnly:true,authority:NONE. Node command exits0 because it prints the refusal; this is NOT a passing test. FULL SOURCE (stdin to node --experimental-transform-types --input-type=module, no file written):
import { openStore, closeStores, driveThrough, envelope, FIXTURE_PUBLICATION_APPROVAL, ALL_HANDLERS } from "./apps/daemon/src/bootstrap/bootstrap-test-fixtures.js";
import { runBootstrapCommand } from "./apps/daemon/src/bootstrap/bootstrap-services.js";
import { createPublishRepository } from "./apps/daemon/src/repository/publish-services.js";
const store = openStore();
try {
  driveThrough(store, "repository.publish");
  const request = envelope("repository.publish", 0, {goalId:"goal-1", remoteUrl:FIXTURE_PUBLICATION_APPROVAL.remoteUrl, approval:FIXTURE_PUBLICATION_APPROVAL}, "probe-real-publication");
  const bytes = new TextEncoder().encode(JSON.stringify(request));
  const result = runBootstrapCommand(store, bytes, {...ALL_HANDLERS, "repository.publish":createPublishRepository()});
  console.log(JSON.stringify(result));
} finally { closeStores(); }

AMENDED STEP6 FEASIBILITY (production-at-claim HEAD17446e73,16:40Z). Exact stdout: {mintedHuman:true,activeGraphs:1}; {httpStatus:422,outcome:'PORT_REFUSED',stage:'DISPATCH',refusal:{code:'PUBLISH_WORKSPACE_UNCONFIGURED',detail:'PUBLISH_WORKSPACE_UNCONFIGURED',httpStatus:422,layer:'DAEMON_PREREQUISITE'}}; {survivors:0,scratchRemoved:true}. Node exit0 is probe completion, NOT deploy/spec success. No repository files edited, no credential material logged. Full source below piped to node --experimental-transform-types --input-type=module; .js fallback resolves lane TS helpers only in the probe process.

import { registerHooks } from "node:module";
import { existsSync } from "node:fs";
registerHooks({ resolve(specifier, context, next) {
  try { return next(specifier, context); } catch (error) {
    if (specifier.endsWith(".js") && context.parentURL) {
      const ts = new URL(specifier.slice(0, -3) + ".ts", context.parentURL);
      if (ts.protocol === "file:" && existsSync(ts)) return next(ts.href, context);
    }
    throw error;
  }
} });
const { default: assert } = await import("node:assert/strict");
const { dirname, join } = await import("node:path");
const { SqliteEventStore } = await import("@moe/store");
const { withDaemonBackedControlRoom, lanePids, survivingPids, readWireProtocolVersion } =
  await import("./tests/e2e/control-room/daemon-ports.ts");
const { createOperatorSessionHandshakePort } = await import("./apps/daemon/src/identity/session-handshake.js");
const { isDurableHumanPrincipal } = await import("./apps/daemon/src/identity/human-approver.js");
const { OPERATOR_CAPABILITIES } = await import("./apps/daemon/src/daemon-command-vocabulary.js");
const { DEFAULT_OPERATOR_PRINCIPAL_ID } = await import("./apps/daemon/src/operator-identity.js");
const { activeCompiledGraphs } = await import("./apps/daemon/src/orchestrator/compiled-node-source.js");
let started;
try {
  const result = await withDaemonBackedControlRoom({liveCredentials:"ATTACHED", fakeDocker:"SUCCESS"}, async lane => {
    started = lane;
    const store = SqliteEventStore.openForProject(join(dirname(lane.catalogPath),"store.sqlite"),lane.projectId);
    let minted, goalId;
    try {
      minted = createOperatorSessionHandshakePort({capabilities:OPERATOR_CAPABILITIES,
        clock:Date.now, operatorPrincipalId:DEFAULT_OPERATOR_PRINCIPAL_ID,
        projectId:lane.projectId, sessionTtlMs:60000, store}).mint();
      assert.equal(minted.ok,true);
      assert.equal(isDurableHumanPrincipal(store,minted.principalId),true);
      const graphs=activeCompiledGraphs(store,lane.projectId);
      assert.equal(graphs.length,1);
      goalId=graphs[0].goalRef;
      console.log(JSON.stringify({mintedHuman:true,activeGraphs:graphs.length}));
    } finally { store.close(); }
    const remoteUrl="https://github.com/example/lane.git";
    const payload={goalId,remoteUrl,approval:{branch:"main",remoteUrl,
      repositoryId:"a".repeat(64),sha:"b".repeat(40)}};
    const response=await fetch(lane.daemonOrigin+"/command",{method:"POST",headers:{
      "content-type":"application/json",origin:lane.daemonOrigin,"x-moe-csrf":lane.csrfToken,
      "x-moe-session-credential":minted.credential,
      "x-moe-protocol-version":await readWireProtocolVersion(lane.repoRoot)},
      body:JSON.stringify({commandId:"paired-human-publication-probe",commandKind:"repository.publish",
        correlationId:"publish-probe",expectedVersion:0,payload,requestDigest:"d".repeat(64),
        schemaVersion:"moe-runtime-command/1",sessionCredential:minted.credential,targetAggregateId:"publish:"+goalId})});
    const answer=await response.json();
    console.log(JSON.stringify({httpStatus:response.status,outcome:answer.outcome,stage:answer.stage,refusal:answer.refusal}));
  });
  assert.equal(result.ok,true);
} finally {
  if(started) {
    const survivors=await survivingPids(lanePids(started));
    assert.deepEqual(survivors,[]);
    assert.equal(existsSync(dirname(started.catalogPath)),false);
    console.log(JSON.stringify({survivors:0,scratchRemoved:true}));
  }
}
